  pts=np.argwhere(lab==k); vals=A[lab==k]; mode=int(np.bincount(vals).argmax()); modes.append(mode); groups.append(pts)
  bboxes.append((pts.min(0),pts.max(0)))
 rr,cc=np.indices(A.shape); ds=[]
 for pts,(lo,hi) in zip(groups,bboxes):
  if kind=='centroid':
   cent=pts.mean(0); d=np.sqrt((rr-cent[0])**2+(cc-cent[1])**2)
  elif kind=='bbox':
